import 'dart:io'; import 'package:flutter/material.dart'; import 'package:intl/intl.dart'; import 'package:image_picker/image_picker.dart'; import '../repositories/app_repo.dart'; import '../services/calculator.dart'; import '../services/location_service.dart';
class WorkEntryScreen extends StatefulWidget{final int? editId;const WorkEntryScreen({super.key,this.editId});@override State<WorkEntryScreen> createState()=>_WorkEntryScreenState();}
class _WorkEntryScreenState extends State<WorkEntryScreen>{final repo=AppRepo();final date=TextEditingController(text:DateFormat('yyyy-MM-dd').format(DateTime.now()));final rate=TextEditingController();final notes=TextEditingController();String type='Per Hour';int? cat,customer;TimeOfDay? start,end;String status='Unpaid';Map<String,num> calc={'minutes':0,'hours':0,'days':0,'amount':0};List<XFile> attachments=[];bool loading=false;
Future<void> pickDate()async{final d=await showDatePicker(context:context,firstDate:DateTime(2000),lastDate:DateTime(2100),initialDate:DateTime.tryParse(date.text)??DateTime.now());if(d!=null)setState(()=>date.text=DateFormat('yyyy-MM-dd').format(d));}
Future<void> pickTime(bool isStart)async{final t=await showTimePicker(context:context,initialTime:isStart?(start??TimeOfDay.now()):(end??TimeOfDay.now()));if(t!=null){setState(()=>isStart?start=t:end=t);recalc();}}
int mins(TimeOfDay t)=>t.hour*60+t.minute;void recalc(){if(start==null||end==null)return;setState(()=>calc=BillingCalculator.calculate(type:type,rate:double.tryParse(rate.text)||0,start:mins(start!),end:mins(end!)));}
Future<void> save()async{if(start==null||end==null||rate.text.isEmpty)return;setState(()=>loading=true);final m={'date':date.text,'category_id':cat,'customer_id':customer,'payment_type':type,'rate':double.tryParse(rate.text)??0,'start_minute':mins(start!),'end_minute':mins(end!),'total_minutes':calc['minutes']!.toInt(),'total_hours':calc['hours'],'total_days':calc['days'],'amount':calc['amount'],'notes':notes.text,'status':status,'created_at':DateTime.now().toIso8601String()};if(widget.editId==null)await repo.insert('work_entries',m);else await repo.update('work_entries',m,'id=?',[widget.editId]);if(mounted)Navigator.pop(context);}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.editId==null?'New Work Entry':'Edit Work Entry')),body:FutureBuilder(future:Future.wait([repo.rows('categories'),repo.rows('customers')]),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final cats=s.data![0],cus=s.data![1];return ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:date,readOnly:true,onTap:pickDate,decoration:const InputDecoration(labelText:'Date',border:OutlineInputBorder(),suffixIcon:Icon(Icons.calendar_month))),const SizedBox(height:12),DropdownButtonFormField<int>(value:cat,decoration:const InputDecoration(labelText:'Work Category',border:OutlineInputBorder()),items:cats.map((x)=>DropdownMenuItem(value:x['id'] as int,child:Text('${x['name']}'))).toList(),onChanged:(v)=>setState(()=>cat=v)),const SizedBox(height:12),DropdownButtonFormField<int>(value:customer,decoration:const InputDecoration(labelText:'Customer / Employer',border:OutlineInputBorder()),items:cus.map((x)=>DropdownMenuItem(value:x['id'] as int,child:Text('${x['name']}'))).toList(),onChanged:(v)=>setState(()=>customer=v)),const SizedBox(height:12),SegmentedButton<String>(segments:const [ButtonSegment(value:'Per Minute',label:Text('Minute')),ButtonSegment(value:'Per Hour',label:Text('Hour')),ButtonSegment(value:'Per Day',label:Text('Day'))],selected:{type},onSelectionChanged:(v){setState(()=>type=v.first);recalc();}),const SizedBox(height:12),TextField(controller:rate,onChanged:(_)=>recalc(),keyboardType:TextInputType.number,decoration:InputDecoration(labelText:'$type Rate',prefixText:'₹ ',border:const OutlineInputBorder())),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>pickTime(true),icon:const Icon(Icons.login),label:Text(start==null?'Start Time':start!.format(c)))),const SizedBox(width:10),Expanded(child:OutlinedButton.icon(onPressed:()=>pickTime(false),icon:const Icon(Icons.logout),label:Text(end==null?'End Time':end!.format(c))))]),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[_line('Total Minutes','${calc['minutes']!.toInt()}'),_line('Total Hours','${calc['hours']!.toStringAsFixed(2)}'),_line('Duration',_duration(calc['minutes']!.toInt())),_line('Amount','₹${calc['amount']!.toStringAsFixed(2)}')] ))),const SizedBox(height:12),DropdownButtonFormField<String>(value:status,decoration:const InputDecoration(labelText:'Payment Status',border:OutlineInputBorder()),items:['Paid','Partial Paid','Unpaid'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>status=v!)),const SizedBox(height:12),TextField(controller:notes,maxLines:3,decoration:const InputDecoration(labelText:'Notes',border:OutlineInputBorder())),const SizedBox(height:12),OutlinedButton.icon(onPressed:()async{final xs=await ImagePicker().pickMultiImage();setState(()=>attachments=xs);},icon:const Icon(Icons.attach_file),label:Text('Attachments (${attachments.length})')),const SizedBox(height:12),OutlinedButton.icon(onPressed:()async{final loc=await LocationService().capture();if(loc!=null&&mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('GPS: ${loc['lat']}, ${loc['lng']}')));},icon:const Icon(Icons.location_on),label:const Text('Capture GPS Location')),const SizedBox(height:20),FilledButton.icon(onPressed:loading?null:save,icon:const Icon(Icons.save),label:Text(loading?'Saving...':'Save Entry'))];}));
Widget _line(String a,String b)=>Padding(padding:const EdgeInsets.symmetric(vertical:4),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(a),Text(b,style:const TextStyle(fontWeight:FontWeight.bold))]));String _duration(int m)=>'${m~/60}h ${m%60}m';}
